package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	input, _ := reader.ReadString('\n')
	str := strings.TrimSpace(input)

	seen := make(map[rune]bool)
	count := 0

	for _, r := range str {
		if !seen[r] {
			seen[r] = true
			count++
		}
	}

	if count%2 == 1 {
		fmt.Println("IGNORE HIM!")
	} else {
		fmt.Println("CHAT WITH HER!")
	}
}

