package main

import (
	"bufio"
	"fmt"
	"os"
)

func solution(str string) {
	count := 0
	for i := 0; i < len(str); i++ {
		j := i - 1
		for j >= 0 {
			if str[i] == str[j] {
				break
			}
			j--
		}
		if j == -1 {
			count++
		}
	}
	if count%2 == 1 {
		fmt.Println("IGNORE HIM!")
		return
	}
	fmt.Println("CHAT WITH HER!")
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		solution(scanner.Text())
	}
}

